code.C:
#include <stdio.h>
#include <string.h>
#include <ctype.h>
int main() {
    char s[1000]; if (!fgets(s, sizeof(s), stdin)) return 0;
    int len = strlen(s);
    while (len > 0 && (s[len-1] == '\n' || s[len-1] == '\r')) s[--len] = '\0';
    int cnt = 0;
    for (int i = 0; i < len; i++) if (!isalnum(s[i])) cnt++;
    printf("%d\n", cnt);
    return 0;
}

